CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, avatar TEXT NOT NULL DEFAULT '', password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','ADMIN')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS movies (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title_mn TEXT NOT NULL, title_original TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', poster_url TEXT NOT NULL DEFAULT '', backdrop_url TEXT NOT NULL DEFAULT '', trailer_url TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', year INTEGER NOT NULL, price INTEGER NOT NULL CHECK(price>=0), total_episodes INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PROCESSING','PUBLISHED','ARCHIVED')), featured INTEGER NOT NULL DEFAULT 0, trending INTEGER NOT NULL DEFAULT 0, new_release INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS genres (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS movie_categories (movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE, category_id TEXT NOT NULL REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY(movie_id,category_id));
CREATE TABLE IF NOT EXISTS movie_genres (movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE, genre_id TEXT NOT NULL REFERENCES genres(id) ON DELETE CASCADE, PRIMARY KEY(movie_id,genre_id));
CREATE TABLE IF NOT EXISTS episodes (id TEXT PRIMARY KEY, movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE, episode_number INTEGER NOT NULL CHECK(episode_number>0), title TEXT NOT NULL, duration REAL NOT NULL DEFAULT 0, is_free INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PROCESSING','READY','PUBLISHED')), media_key TEXT, subtitle_key TEXT, thumbnail_url TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(movie_id,episode_number));
CREATE TABLE IF NOT EXISTS processing_jobs (job_id TEXT PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES episodes(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subtitles (id TEXT PRIMARY KEY, episode_id TEXT NOT NULL REFERENCES episodes(id) ON DELETE CASCADE, language TEXT NOT NULL DEFAULT 'mn', storage_key TEXT NOT NULL, UNIQUE(episode_id,language));
CREATE TABLE IF NOT EXISTS purchases (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), movie_id TEXT NOT NULL REFERENCES movies(id), amount INTEGER NOT NULL CHECK(amount>=0), status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PAID','CANCELLED')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,movie_id));
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), purchase_id TEXT NOT NULL UNIQUE REFERENCES purchases(id), provider TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PAID','CANCELLED')), transaction_id TEXT UNIQUE, verified_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS watch_progress (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, episode_id TEXT NOT NULL REFERENCES episodes(id) ON DELETE CASCADE, current_time REAL NOT NULL, duration REAL NOT NULL, completed INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,episode_id));
CREATE TABLE IF NOT EXISTS favorites (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, movie_id TEXT NOT NULL REFERENCES movies(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,movie_id));
CREATE INDEX IF NOT EXISTS movies_status ON movies(status,created_at);
CREATE INDEX IF NOT EXISTS episodes_movie ON episodes(movie_id,status,episode_number);
CREATE INDEX IF NOT EXISTS progress_user ON watch_progress(user_id,updated_at);
